@Slf4j
@RequiredArgsConstructor
@Component
public class AppSessionService {

  private static final Integer TOKEN_PADDING_LENGTH = 1;
  /**
   * The {@link VerificationAppSessionRepository}.
   */
  @NonNull
  private final VerificationAppSessionRepository appSessionRepository;

  /**
   * The {@link HashingService}.
   */
  @NonNull
  private final HashingService hashingService;

  /**
   * Creates an AppSession-Entity.
   *
   * @param registrationToken Token for registration
   * @return appSession for registrationToken
   */
  public VerificationAppSession generateAppSession(String registrationToken) {
    log.info("Create the app session entity with the created registration token.");
    VerificationAppSession appSession = new VerificationAppSession();
    appSession.setCreatedAt(LocalDateTime.now());
    appSession.setUpdatedAt(LocalDateTime.now());
    appSession.setRegistrationTokenHash(hashingService.hash(registrationToken));
    return appSession;
  }

  private String generateRegistrationToken() {
    return UUID.randomUUID().toString();
  }

  /**
   * This method generates a registration Token by a guid .
   *
   * @param hashedGuid the hashed guid
   * @return an {@link ResponseEntity}
   */
  public ResponseEntity<RegistrationToken> generateRegistrationTokenByGuid(
    String hashedGuid, String hashedGuidDob, String fake) {

    if (checkRegistrationTokenAlreadyExistsForGuid(hashedGuid)) {
      log.warn("The registration token already exists for the hashed guid.");
      return ResponseEntity.badRequest().build();
    }

    if (hashedGuidDob != null && checkRegistrationTokenAlreadyExistsForGuid(hashedGuidDob)) {
      log.warn("The registration token already exists for the hashed guid dob.");
      return ResponseEntity.badRequest().build();
    }

    log.info("Start generating a new registration token for the given hashed guid.");

    String registrationToken = generateRegistrationToken();
    VerificationAppSession appSession = generateAppSession(registrationToken);
    appSession.setHashedGuid(hashedGuid);
    appSession.setHashedGuidDob(hashedGuidDob);
    appSession.setSourceOfTrust(AppSessionSourceOfTrust.HASHED_GUID);

    try {
      saveAppSession(appSession);
    } catch (DataIntegrityViolationException e) {
      log.error("Failed to save RegistrationToken because of Hashed GUID Conflict: {}", hashedGuid);
      throw new VerificationServerException(
        HttpStatus.BAD_REQUEST, "Failed to save RegistrationToken because of Hashed GUID Conflict");
    }

    log.info("Returning the successfully created registration token.");
    return ResponseEntity.status(HttpStatus.CREATED).body(
      getBackwardCompatibleRegistrationToken(registrationToken, fake));

  }

  /**
   * This method generates a registration Token by a TeleTAN.
   *
   * @param teleTan the TeleTan
   * @return an {@link ResponseEntity}
   */
  public ResponseEntity<RegistrationToken> generateRegistrationTokenByTeleTan(
    String teleTan, String fake, TeleTanType teleTanType) {
    if (checkRegistrationTokenAlreadyExistForTeleTan(teleTan)) {
      log.warn("The registration token already exists for this TeleTAN.");
      return ResponseEntity.badRequest().build();
    } else {
      log.info("Start generating a new registration token for the given TeleTAN.");
      String registrationToken = generateRegistrationToken();
      VerificationAppSession appSession = generateAppSession(registrationToken);
      appSession.setTeleTanHash(hashingService.hash(teleTan));
      appSession.setSourceOfTrust(AppSessionSourceOfTrust.TELETAN);
      appSession.setTeleTanType(teleTanType);
      saveAppSession(appSession);
      log.info("Returning the successfully created registration token.");
      return ResponseEntity.status(HttpStatus.CREATED).body(
        getBackwardCompatibleRegistrationToken(registrationToken, fake));
    }
  }

  /**
   * Persists the specified entity of {@link VerificationAppSession} instances.
   *
   * @param appSession the verification app session entity
   */
  public void saveAppSession(VerificationAppSession appSession) {
    log.info("Start saveAppSession.");
    appSessionRepository.save(appSession);
  }

  /**
   * Get existing VerificationAppSession for Reg Token from {@link VerificationAppSessionRepository}.
   *
   * @param registrationToken the registrationToken
   * @return Optional VerificationAppSession
   */
  public Optional<VerificationAppSession> getAppSessionByToken(String registrationToken) {
    log.info("Start getAppSessionByToken.");
    return appSessionRepository.findByRegistrationTokenHash(hashingService.hash(registrationToken));
  }

  /**
   * Check for existing hashed GUID Token in the {@link VerificationAppSessionRepository}.
   *
   * @param hashedGuid the hashed guid
   * @return flag for existing guid
   */
  public boolean checkRegistrationTokenAlreadyExistsForGuid(String hashedGuid) {
    log.info("Start checkRegistrationTokenAlreadyExistsForGuid.");
    return appSessionRepository.findByHashedGuidOrHashedGuidDob(hashedGuid, hashedGuid).isPresent();
  }

  /**
   * Check for existing hashed TeleTAN in the {@link VerificationAppSessionRepository}.
   *
   * @param teleTan the teleTAN
   * @return flag for existing teleTAN
   */
  public boolean checkRegistrationTokenAlreadyExistForTeleTan(String teleTan) {
    log.info("Start checkTeleTanAlreadyExistForTeleTan.");
    return appSessionRepository.findByTeleTanHash(hashingService.hash(teleTan)).isPresent();
  }

  private RegistrationToken getBackwardCompatibleRegistrationToken(String registrationToken, String fake) {
    if (fake == null) {
      return new RegistrationToken(registrationToken);
    }
    return new RegistrationToken(registrationToken, RandomStringUtils.randomAlphanumeric(TOKEN_PADDING_LENGTH));
  }
}

@Component
public class FakeDelayService {

  private final long movingAverageSampleSize;
  private long fakeDelayTest;

  private long fakeDelayTan;

  private long fakeDelayToken;

  /**
   * Constructor for the FakeDelayService.
   */
  public FakeDelayService(VerificationApplicationConfig applicationConfig) {
    this.fakeDelayTest = applicationConfig.getInitialFakeDelayMilliseconds();
    this.fakeDelayTan = applicationConfig.getInitialFakeDelayMilliseconds();
    this.fakeDelayToken = applicationConfig.getInitialFakeDelayMilliseconds();
    this.movingAverageSampleSize = applicationConfig.getFakeDelayMovingAverageSamples();
  }

  /**
   * Returns the current fake delay after applying random jitter.
   */
  public long getJitteredFakeTanDelay() {
    return new PoissonDistribution(fakeDelayTan).sample();
  }

  /**
   * Returns the current fake delay after applying random jitter.
   */
  public long getJitteredFakeTestDelay() {
    return new PoissonDistribution(fakeDelayTest).sample();
  }

  /**
   * Returns the current fake delay after applying random jitter.
   */
  public long getJitteredFakeTokenDelay() {
    return new PoissonDistribution(fakeDelayToken).sample();
  }

  /**
   * Updates the moving average for the request duration for the Tan Endpoint with the specified value.
   */
  public void updateFakeTanRequestDelay(long realRequestDuration) {
    final long currentDelay = fakeDelayTan;
    fakeDelayTan = currentDelay + (realRequestDuration - currentDelay) / movingAverageSampleSize;
  }

  /**
   * Updates the moving average for the request duration for the Tan Endpoint with the specified value.
   */
  public void updateFakeTestRequestDelay(long realRequestDuration) {
    final long currentDelay = fakeDelayTest;
    fakeDelayTan = currentDelay + (realRequestDuration - currentDelay) / movingAverageSampleSize;
  }

  /**
   * Updates the moving average for the request duration for the Tan Endpoint with the specified value.
   */
  public void updateFakeTokenRequestDelay(long realRequestDuration) {
    final long currentDelay = fakeDelayToken;
    fakeDelayTan = currentDelay + (realRequestDuration - currentDelay) / movingAverageSampleSize;
  }

  /**
   * Returns the current fake delay in seconds. Used for monitoring.
   */
  public Double getFakeTanDelayInSeconds() {
    return fakeDelayTan / 1000.;
  }

  /**
   * Returns the current fake delay in seconds. Used for monitoring.
   */
  public Double getFakeTestDelayInSeconds() {
    return fakeDelayTest / 1000.;
  }

  /**
   * Returns the current fake delay in seconds. Used for monitoring.
   */
  public Double getFakeTokenDelayInSeconds() {
    return fakeDelayToken / 1000.;
  }

  /**
   * Returns the longest fake delay jittered in milliseconds.
   * @return longest jittered
   */
  public long getLongestJitter() {
    if ((fakeDelayTan > fakeDelayTest) && (fakeDelayTan > fakeDelayToken)) {
      return getJitteredFakeTanDelay();
    } else if ((fakeDelayToken > fakeDelayTest) && (fakeDelayToken > fakeDelayTan)) {
      return getJitteredFakeTokenDelay();
    } else {
      return getJitteredFakeTestDelay();
    }
  }

  /**
   * Returns the longest fake delay minus average time for Tan in milliseconds.
   * @return delay for TAN
   */
  public long realDelayTan() {
    return (getLongestJitter() - getJitteredFakeTanDelay());
  }

  /**
   * Returns the longest fake delay minus average time for RegistrationToken in milliseconds.
   * @return delay for RegistrationToken
   */
  public long realDelayToken() {
    return (getLongestJitter() - getJitteredFakeTokenDelay());
  }

  /**
   * Returns the longest fake delay minus average time for TestResult in milliseconds.
   * @return delay for TestResult
   */
  public long realDelayTest() {
    return (getLongestJitter() - getJitteredFakeTestDelay());
  }
}

@Slf4j
@Service
@RequiredArgsConstructor
public class FakeRequestService {

  @NonNull
  private final FakeDelayService fakeDelayService;

  private final ScheduledExecutorService scheduledExecutor = Executors.newScheduledThreadPool(4);

  private static final Integer TEST_RESPONSE_PADDING_LENGTH = 45;
  private static final Integer TESTRESULT_RESULT_PADDING = 1;
  private static final Integer TAN_RESPONSE_PADDING_LENGTH = 15;


  /**
   * This method generates a fake transaction number by a Registration Token, if the state of the COVID-19 lab-test is
   * positive.
   *
   * @param registrationToken generated by a hashed guid or a teleTAN. {@link RegistrationToken}
   * @return A generated transaction number {@link Tan}.
   */
  public DeferredResult<ResponseEntity<Tan>> generateTan(@Valid @RequestBody RegistrationToken registrationToken) {
    long delay = fakeDelayService.getLongestJitter();
    DeferredResult<ResponseEntity<Tan>> deferredResult = new DeferredResult<>();
    Tan returnTan = new Tan(UUID.randomUUID().toString(),
      RandomStringUtils.randomAlphanumeric(TAN_RESPONSE_PADDING_LENGTH));
    scheduledExecutor.schedule(() -> deferredResult.setResult(ResponseEntity.status(HttpStatus.CREATED)
      .body(returnTan)), delay, MILLISECONDS);
    return deferredResult;
  }


  /**
   * This method generates a fake registrationToken by a hashed guid or a teleTAN.
   *
   * @param request {@link RegistrationTokenRequest}
   * @return RegistrationToken - the created registration token {@link RegistrationToken}
   */
  public DeferredResult<ResponseEntity<RegistrationToken>> generateRegistrationToken(
    @RequestBody @Valid RegistrationTokenRequest request) {
    long delay = fakeDelayService.getLongestJitter();
    DeferredResult<ResponseEntity<RegistrationToken>> deferredResult = new DeferredResult<>();
    scheduledExecutor.schedule(() -> deferredResult.setResult(ResponseEntity.status(HttpStatus.CREATED)
      .body(new RegistrationToken(UUID.randomUUID().toString(),
        RandomStringUtils.randomAlphanumeric(TESTRESULT_RESULT_PADDING)))), delay, MILLISECONDS);
    return deferredResult;
  }


  /**
   * Returns the fake test status of the COVID-19 test.
   *
   * @param registrationToken generated by a hashed guid {@link RegistrationToken}
   * @return the test result / status of the COVID-19 test, which can be POSITIVE, NEGATIVE, INVALID, PENDING or FAILED
   *     and will always be POSITIVE for a TeleTan.
   */
  public DeferredResult<ResponseEntity<TestResult>> getTestState(
    @Valid @RequestBody RegistrationToken registrationToken) {
    long delay = fakeDelayService.getLongestJitter();
    DeferredResult<ResponseEntity<TestResult>> deferredResult = new DeferredResult<>();
    scheduledExecutor.schedule(() -> deferredResult.setResult(ResponseEntity
      .ok(new TestResult(LabTestResult.POSITIVE.getTestResult(), LocalDateTime.now().toEpochSecond(ZoneOffset.UTC),
        null, RandomStringUtils.randomAlphanumeric(TEST_RESPONSE_PADDING_LENGTH)))), delay, MILLISECONDS);
    return deferredResult;
  }

}

@Slf4j
@Component
public class TanService {


  private final VerificationApplicationConfig verificationApplicationConfig;

  /**
   * The {@link VerificationTanRepository}.
   */
  private final VerificationTanRepository tanRepository;
  /**
   * The {@link HashingService}.
   */
  private final HashingService hashingService;

  private final Pattern teleTanPattern;
  private final int teleTanLength;

  /**
   * Constructor for the TanService that also builds the pattern for tele tan verification.
   *
   * @param verificationApplicationConfig the {@link VerificationApplicationConfig} with needed tan configurations
   * @param tanRepository the {@link VerificationTanRepository} where tans are queried and inserted
   * @param hashingService the {@link HashingService} implementation
   */
  public TanService(
    @NonNull VerificationApplicationConfig verificationApplicationConfig,
    @NonNull VerificationTanRepository tanRepository,
    @NonNull HashingService hashingService
  ) {
    this.verificationApplicationConfig = verificationApplicationConfig;
    this.tanRepository = tanRepository;
    this.hashingService = hashingService;
    this.teleTanLength = verificationApplicationConfig.getTan().getTele().getValid().getLength();
    this.teleTanPattern = Pattern.compile("^["
      + verificationApplicationConfig.getTan().getTele().getValid().getChars()
      + "]{"
      + (verificationApplicationConfig.getTan().getTele().getValid().getLength() + 1)
      + "}$");
  }

  /**
   * Saves a {@link VerificationTan} into the database.
   *
   * @param tan {@link VerificationTan}
   * @return {@link VerificationTan}
   */
  public VerificationTan saveTan(VerificationTan tan) {
    return tanRepository.save(tan);
  }

  /**
   * Deletes a {@link VerificationTan} from the database.
   *
   * @param tan the tan which will be deleted
   */
  public void deleteTan(VerificationTan tan) {
    tanRepository.delete(tan);
  }

  /**
   * Check teleTAN syntax constraints.
   *
   * @param teleTan the teleTAN
   * @return teleTAN verification flag
   */
  private boolean syntaxTeleTanVerification(String teleTan) {
    Matcher matcher = teleTanPattern.matcher(teleTan);
    return matcher.find();
  }

  /**
   * Verifies the tele transaction number (teleTAN).
   *
   * @param teleTan the teleTAN to verify
   * @return is teleTAN verified
   */
  public boolean verifyTeleTan(String teleTan) {
    boolean verified = false;
    if (syntaxTeleTanVerification(teleTan)) {
      Optional<VerificationTan> teleTanEntity = getEntityByTan(teleTan);
      if (teleTanEntity.isPresent() && teleTanEntity.get().canBeRedeemed(LocalDateTime.now())) {
        verified = true;
      } else {
        log.warn("The teleTAN is unknown, expired or already redeemed.");
      }
    } else {
      log.warn("The teleTAN is not valid to the syntax constraints.");
    }
    return verified;
  }

  /**
   * Generates a new, valid TAN String.
   * A TAN is considered as valid if it is not yet stored in the database.
   *
   * @param tanCreator a supplier which creates a new TAN
   * @return a Valid TAN String
   */
  protected String generateValidTan(Supplier<String> tanCreator) {
    boolean validTan = false;
    String newTan = "";
    while (!validTan) {
      newTan = tanCreator.get();
      validTan = checkTanNotExist(newTan);
    }
    return newTan;
  }

  /**
   * This method generates a {@link VerificationTan} - entity and saves it.
   *
   * @param tan     the TAN
   * @param tanType the TAN type
   * @param teleTanType type of the teleTan
   * @return the persisted TAN
   */
  private VerificationTan persistTan(
    String tan, TanType tanType, TanSourceOfTrust sourceOfTrust, TeleTanType teleTanType) {
    VerificationTan newTan = generateVerificationTan(tan, tanType, sourceOfTrust, teleTanType);
    return tanRepository.save(newTan);
  }

  /**
   * Creates a new TeleTan String.
   *
   * @return a new teleTAN
   */
  protected String createTeleTan() {
    final int length = verificationApplicationConfig.getTan().getTele().getValid().getLength();
    final String chars = verificationApplicationConfig.getTan().getTele().getValid().getChars();
    String teletan = IntStream.range(0, length)
      .mapToObj(i -> chars.charAt(Holder.NUMBER_GENERATOR.nextInt(chars.length())))
      .collect(Collector.of(
        StringBuilder::new,
        StringBuilder::append,
        StringBuilder::append,
        StringBuilder::toString));
    return teletan + hashingService.getCheckDigit(teletan);

  }

  /**
   * Returns the if a teleTAN matches the Pattern requirements.
   *
   * @param teleTan the teleTAN to check
   * @return The validity of the teleTAN
   */
  public boolean isTeleTanValid(String teleTan) {
    return syntaxTeleTanVerification(teleTan);
  }

  /**
   * Created a new TAN String.
   *
   * @return a new TAN
   */
  protected String createTanFromUuid() {
    // A UUID is a 128 bit value
    return UUID.randomUUID().toString();
  }

  /**
   * Check for existing TAN in the {@link VerificationTanRepository}.
   *
   * @param tan the TAN
   * @return flag for existing TAN
   */
  public boolean checkTanNotExist(String tan) {
    String tanHash = hashingService.hash(tan);
    return !tanRepository.existsByTanHash(tanHash);
  }

  /**
   * Returns a generated valid teleTAN and persists it.
   *
   * @return a valid teleTAN
   */
  public String generateVerificationTeleTan(@NotNull TeleTanType teleTanType) {
    String teleTan = generateValidTan(this::createTeleTan);
    persistTan(teleTan, TanType.TELETAN, TanSourceOfTrust.TELETAN, teleTanType);
    return teleTan;
  }

  /**
   * This Method generates a valid TAN and persists it. Returns the generated TAN.
   *
   * @param sourceOfTrust sets the source of Trust for the Tan
   * @param teleTanType type of the teleTan
   * @return a valid tan with given source of Trust
   */
  public String generateVerificationTan(TanSourceOfTrust sourceOfTrust, TeleTanType teleTanType) {
    String tan = generateValidTan(this::createTanFromUuid);
    persistTan(tan, TanType.TAN, sourceOfTrust, teleTanType);
    return tan;
  }

  /**
   * This method generates a valid TAN Object but doesn't persist it.
   * @param tan alphanumeric tan
   * @param tanType type of the tan
   * @param sourceOfTrust source of trust of the tan
   * @return Tan object
   */
  public VerificationTan generateVerificationTan(
    String tan, TanType tanType, TanSourceOfTrust sourceOfTrust, TeleTanType teleTanType) {

    LocalDateTime from = LocalDateTime.now();
    LocalDateTime until;
    int tanValidInDays = verificationApplicationConfig.getTan().getValid().getDays();
    int teleTanValidInHours = verificationApplicationConfig.getTan().getTele().getValid().getHours();
    int eventTeleTanValidInDays = verificationApplicationConfig.getTan().getTele().getValid().getEventDays();

    if (tanType == TanType.TELETAN) {
      if (teleTanType == TeleTanType.TEST) {
        until = from.plusHours(teleTanValidInHours);
      } else {
        until = from.plusDays(eventTeleTanValidInDays);
      }
    } else {
      until = from.plusDays(tanValidInDays);
    }

    VerificationTan verificationTan = new VerificationTan();
    verificationTan.setTanHash(hashingService.hash(tan));
    verificationTan.setValidFrom(from);
    verificationTan.setValidUntil(until);
    verificationTan.setSourceOfTrust(sourceOfTrust);
    verificationTan.setRedeemed(false);
    verificationTan.setCreatedAt(LocalDateTime.now());
    verificationTan.setUpdatedAt(LocalDateTime.now());
    verificationTan.setType(tanType);
    verificationTan.setTeleTanType(teleTanType);
    return verificationTan;
  }

  /**
   * Get existing VerificationTan by TAN from {@link VerificationTanRepository}.
   *
   * @param tan the TAN
   * @return Optional VerificationTan
   */
  public Optional<VerificationTan> getEntityByTan(String tan) {
    log.info("Start getEntityByTan.");
    return tanRepository.findByTanHash(hashingService.hash(tan));
  }

  /**
   * Checks whether the rate limit for new TeleTans is not exceeded.
   *
   * @return true if new TeleTans can be created false if not.
   */
  public boolean isTeleTanRateLimitNotExceeded() {
    int maxNumberOfTans = verificationApplicationConfig.getTan().getTele().getRateLimiting().getCount();
    int thresholdInPercent = verificationApplicationConfig.getTan().getTele().getRateLimiting().getThresholdInPercent();
    int thresholdTans = thresholdInPercent * maxNumberOfTans / 100;
    int timeWindow = verificationApplicationConfig.getTan().getTele().getRateLimiting().getSeconds();

    LocalDateTime timestamp = LocalDateTime.now().minusSeconds(timeWindow);
    int countedTans = tanRepository.countByCreatedAtIsAfterAndTypeIs(timestamp, TanType.TELETAN);

    boolean result = countedTans < maxNumberOfTans;

    if (!result) {
      log.warn("The TeleTan rate limit is exceeded! (maximum {} tans within {} seconds)", maxNumberOfTans, timeWindow);
    } else if (countedTans >= thresholdTans) {
      log.warn("The TeleTan rate limit threshold of {}% is reached!"
        + " (maximum {} tans within {} seconds)", thresholdInPercent, maxNumberOfTans, timeWindow);
    }

    return result;
  }

  /*
   * The random number generator used by this class to create random
   * based UUIDs. In a holder class to defer initialization until needed.
   */
  private static class Holder {

    static final SecureRandom NUMBER_GENERATOR = new SecureRandom();
  }
}

