@Configuration
@RequiredArgsConstructor

public class TestResultServerClientConfig {

  @Value("${cwa-testresult-server.ssl.enabled}")
  private boolean enabled;
  @Value("${cwa-testresult-server.ssl.one-way}")
  private boolean oneWay;
  @Value("${cwa-testresult-server.ssl.two-way}")
  private boolean twoWay;
  @Value("${cwa-testresult-server.ssl.hostname-verify}")
  private boolean hostnameVerify;
  @Value("${cwa-testresult-server.ssl.key-store}")
  private String keyStorePath;
  @Value("${cwa-testresult-server.ssl.key-store-password}")
  private char[] keyStorePassword;
  @Value("${cwa-testresult-server.ssl.trust-store}")
  private String trustStorePath;
  @Value("${cwa-testresult-server.ssl.trust-store-password}")
  private char[] trustStorePassword;

  /**
   * Configure the client dependent on the ssl properties.
   *
   * @return an Apache Http Client with or without SSL features
   */
  @Bean
  public Client client() {
    if (enabled) {
      return new ApacheHttpClient(
        HttpClientBuilder
          .create()
          .setSSLContext(getSslContext())
          .setSSLHostnameVerifier(getSslHostnameVerifier())
          .build()
      );
    }
    return new ApacheHttpClient(HttpClientBuilder.create()
      .setSSLHostnameVerifier(getSslHostnameVerifier())
      .build());
  }

  private SSLContext getSslContext() {
    try {
      SSLContextBuilder builder = SSLContextBuilder
        .create();
      if (oneWay) {
        builder.loadTrustMaterial(ResourceUtils.getFile(trustStorePath),
          trustStorePassword);
      }
      if (twoWay) {
        builder.loadKeyMaterial(ResourceUtils.getFile(keyStorePath),
          keyStorePassword,
          keyStorePassword);
      }
      return builder.build();
    } catch (IOException | GeneralSecurityException e) {
      throw new VerificationServerException(HttpStatus.INTERNAL_SERVER_ERROR, "The SSL context could not be loaded.");
    }
  }

  private HostnameVerifier getSslHostnameVerifier() {
    return hostnameVerify ? new DefaultHostnameVerifier() : new NoopHostnameVerifier();
  }

}

@Slf4j
@RestControllerAdvice
public class VerificationExceptionHandler {

  /**
   * This method handles unknown Exceptions and Server Errors.
   *
   * @param ex the thrown exception
   * @param wr the WebRequest
   */
  @ExceptionHandler(Exception.class)
  @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
  public void unknownException(Exception ex, WebRequest wr) {
    log.error("Unable to handle {}", wr.getDescription(false), ex);
  }

  /**
   * This method handles Bad Requests.
   *
   * @param ex the thrown exception
   * @param wr the WebRequest
   */
  @ExceptionHandler({
    HttpMessageNotReadableException.class,
    ServletRequestBindingException.class
  })
  @ResponseStatus(HttpStatus.BAD_REQUEST)
  public void bindingExceptions(Exception ex, WebRequest wr) {
    log.error("Binding failed {}", wr.getDescription(false), ex);
  }

  /**
   * This method handles Validation Exceptions.
   *
   * @return ResponseEntity<?> returns Bad Request
   */
  @ExceptionHandler({
    MethodArgumentNotValidException.class,
    ConstraintViolationException.class
  })
  public ResponseEntity<?> handleValidationExceptions() {
    return ResponseEntity.badRequest().build();
  }

  /**
   * This method handles Validation Exceptions.
   *
   * @param exception the thrown exception
   * @return ResponseEntity<?> returns a HTTP Status
   */
  @ExceptionHandler(VerificationServerException.class)
  public ResponseEntity<Void> handleVerificationServerExceptions(VerificationServerException exception) {
    log.warn("The verification server response preventation due to: {}", exception.getMessage());
    return ResponseEntity.status(exception.getHttpStatus()).build();
  }

  /**
   * This method handles invalid HTTP methods.
   *
   * @param ex the thrown exception
   * @param wr the WebRequest
   */
  @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
  @ResponseStatus(HttpStatus.METHOD_NOT_ALLOWED)
  public void methodNotAllowedException(Exception ex, WebRequest wr) {
    log.warn("Invalid http method {}", wr.getDescription(false), ex);
  }

  /**
   * This method handles unsupported content types.
   *
   * @param ex the thrown exception
   * @param wr the WebRequest
   */
  @ExceptionHandler(HttpMediaTypeNotSupportedException.class)
  @ResponseStatus(HttpStatus.UNSUPPORTED_MEDIA_TYPE)
  public void contentTypeNotAllowedException(Exception ex, WebRequest wr) {
    log.warn("Unsupported content type {}", wr.getDescription(false), ex);
  }
}
